import data from './communes.data.json';
import { WILAYA_MAX, WILAYA_MIN, WILAYAS } from './wilayas';

export interface Commune {
  /** The 4 digit ONS code as a number (`0101` is 101). It does not change with the wilaya. */
  code: number;
  wilayaCode: number;
  /** Wilayas of the 58 and 48 wilaya maps that differ from the current one. */
  formerWilayaCodes: readonly number[];
  fr: string;
  ar: string;
  dairaKey: string | null;
  /** Other official or common spellings. */
  aliases: readonly string[];
}

export interface Daira {
  /** Stable, unique per wilaya and name. */
  key: string;
  wilayaCode: number;
  fr: string;
  /** Null when it cannot be derived from the seat commune. */
  ar: string | null;
}

type CommuneRow = [number, number, number[], string, string, string | null, string[]];
type DairaRow = [string, number, string, string | null];
type WilayaRow = [number, string, string];

// TypeScript widens the JSON rows to mixed arrays, hence the casts. The tests check the shape.
const COMMUNES: readonly Commune[] = (data.communes as unknown as CommuneRow[]).map(
  ([code, wilayaCode, formerWilayaCodes, fr, ar, dairaKey, aliases]) =>
    Object.freeze({ code, wilayaCode, formerWilayaCodes, fr, ar, dairaKey, aliases }),
);
const DAIRAS: readonly Daira[] = (data.dairas as unknown as DairaRow[]).map(
  ([key, wilayaCode, fr, ar]) => Object.freeze({ key, wilayaCode, fr, ar }),
);

function groupByWilaya<T extends { wilayaCode: number }>(items: readonly T[]): Map<number, T[]> {
  const groups = new Map<number, T[]>();
  for (const item of items) {
    const group = groups.get(item.wilayaCode);
    if (group) group.push(item);
    else groups.set(item.wilayaCode, [item]);
  }
  return groups;
}

const COMMUNE_BY_CODE = new Map(COMMUNES.map((c) => [c.code, c]));
const DAIRA_BY_KEY = new Map(DAIRAS.map((d) => [d.key, d]));
const COMMUNES_BY_WILAYA = groupByWilaya(COMMUNES);
const DAIRAS_BY_WILAYA = groupByWilaya(DAIRAS);

/** The communes of a wilaya (current map), ordered by code. */
export function communesOf(wilayaCode: number): readonly Commune[] {
  return COMMUNES_BY_WILAYA.get(wilayaCode) ?? [];
}

/** The dairas of a wilaya, ordered by key. */
export function dairasOf(wilayaCode: number): readonly Daira[] {
  return DAIRAS_BY_WILAYA.get(wilayaCode) ?? [];
}

/**
 * Every commune a zone covers (phase 40b): its own communes plus all the communes of its
 * whole wilayas, ordered, without duplicates.
 */
export function zoneCommuneCodes(zone: {
  wilayaCodes: readonly number[];
  communeCodes: readonly number[];
}): number[] {
  const codes = new Set(zone.communeCodes);
  for (const wilayaCode of zone.wilayaCodes) {
    for (const commune of communesOf(wilayaCode)) codes.add(commune.code);
  }
  return [...codes].sort((a, b) => a - b);
}

export function communeByCode(code: number | null | undefined): Commune | null {
  return code == null ? null : (COMMUNE_BY_CODE.get(code) ?? null);
}

export function dairaByKey(key: string | null | undefined): Daira | null {
  return key == null ? null : (DAIRA_BY_KEY.get(key) ?? null);
}

// ---------------------------------------------------------------------------
// Review gate
// ---------------------------------------------------------------------------

/**
 * The owner approved `docs/review/communes-59-69.md` on 2026-11-28, so the gate is open. While
 * false, the communes of wilayas 59 to 69 cannot be saved on anything (the wilaya code alone
 * is allowed). The gate stays in the code for a later list that needs the same review.
 */
export const COMMUNES_59_69_REVIEWED: boolean = true;

const GATED_WILAYA_MIN = 59;
const GATED_WILAYA_MAX = 69;

/** `reviewed` exists so that tests can exercise the open state; callers leave it out. */
export function isCommuneUnderReview(
  code: number | null | undefined,
  reviewed: boolean = COMMUNES_59_69_REVIEWED,
): boolean {
  const commune = communeByCode(code);
  if (reviewed || !commune) return false;
  return commune.wilayaCode >= GATED_WILAYA_MIN && commune.wilayaCode <= GATED_WILAYA_MAX;
}

// ---------------------------------------------------------------------------
// Text matching
// ---------------------------------------------------------------------------

/**
 * The form two spellings of the same name share: no case, Latin accents, Arabic diacritics,
 * spaces, hyphens or apostrophes, and one form for each Arabic letter variant.
 */
function exactKey(text: string): string {
  return (
    text
      // NFD splits accents and the hamza or madda of a letter into combining marks.
      .normalize('NFD')
      .replace(/\p{M}/gu, '')
      .toLowerCase()
      .replaceAll('œ', 'oe')
      .replaceAll('ى', 'ي') // alef maksura
      .replaceAll('ی', 'ي') // Farsi yeh
      .replaceAll('ة', 'ه') // teh marbuta
      .replaceAll('ک', 'ك') // Farsi kaf
      .replaceAll('ٱ', 'ا') // alef wasla
      .replaceAll('ـ', '') // tatweel
      // Keeps letters and digits only. The apostrophe look-alikes are letters in Unicode.
      .replace(/[^\p{L}\p{N}]|[ʹʻʼʽʾʿˈ]/gu, '')
  );
}

/** Evens out the usual ways of writing an Arabic name in Latin letters. Suggestions only. */
function looseKey(text: string): string {
  const key = exactKey(text);
  if (!/[a-z]/.test(key)) return '';
  const withoutArticle = key.replace(/^(?:el|al)(?=.{3})/, '');
  return withoutArticle
    .replaceAll('dj', 'j')
    .replaceAll('ou', 'u')
    .replaceAll('sh', 'ch')
    .replaceAll('ph', 'f')
    .replaceAll('w', 'u')
    .replaceAll('o', 'u')
    .replaceAll('y', 'i')
    .replaceAll('q', 'k')
    .replaceAll('e', 'a')
    .replace(/(.)\1+/g, '$1')
    .replace(/h$/, '');
}

export type CommuneMatch = 'exact' | 'loose';

export interface CommuneCandidate {
  commune: Commune;
  match: CommuneMatch;
}

const SEARCH_KEYS = new Map(
  COMMUNES.map((c) => {
    const names = [c.fr, c.ar, ...c.aliases];
    return [
      c.code,
      {
        exact: new Set(names.map(exactKey)),
        loose: new Set(names.map(looseKey).filter(Boolean)),
      },
    ];
  }),
);

function matchAmong(text: string, communes: readonly Commune[]): CommuneCandidate[] {
  const wanted = exactKey(text);
  if (!wanted) return [];
  const wantedLoose = looseKey(text);
  const exact: CommuneCandidate[] = [];
  const loose: CommuneCandidate[] = [];
  for (const commune of communes) {
    const keys = SEARCH_KEYS.get(commune.code)!;
    if (keys.exact.has(wanted)) exact.push({ commune, match: 'exact' });
    else if (wantedLoose && keys.loose.has(wantedLoose)) loose.push({ commune, match: 'loose' });
  }
  return [...exact, ...loose];
}

/**
 * Every commune whose name or alias matches the text, exact matches first. It never picks one:
 * the caller decides. `wilayaCode` limits the search to that wilaya of the current map.
 */
export function findCommune(text: string, wilayaCode?: number): CommuneCandidate[] {
  return matchAmong(text, wilayaCode === undefined ? COMMUNES : communesOf(wilayaCode));
}

const WILAYA_BY_KEY = new Map<string, number>(
  [
    ...WILAYAS.map((w): WilayaRow => [w.code, w.fr, w.ar]),
    // The dataset spells some names differently (Tamanghasset, Aïn Ouessara...).
    ...(data.wilayas as unknown as WilayaRow[]),
  ].flatMap(([code, fr, ar]) => [
    [exactKey(fr), code],
    [exactKey(ar), code],
  ]),
);

/**
 * The wilaya code written as a number, a French or Arabic name, or both (`28 · M'Sila`);
 * null when unsure, including a number and a name that disagree.
 */
export function findWilaya(text: string | null | undefined): number | null {
  const [, digits, rest = ''] = /^\s*(\d+)(.*)$/s.exec(text ?? '') ?? [];
  if (digits === undefined) return WILAYA_BY_KEY.get(exactKey(text ?? '')) ?? null;
  const code = Number(digits);
  if (digits.length > 2 || code < WILAYA_MIN || code > WILAYA_MAX) return null;
  if (!exactKey(rest)) return code;
  return WILAYA_BY_KEY.get(exactKey(rest)) === code ? code : null;
}

// ---------------------------------------------------------------------------
// Old free text -> codes
// ---------------------------------------------------------------------------

export type LocationStatus =
  | 'MATCHED'
  | 'MATCHED_FORMER_WILAYA'
  | 'WILAYA_ONLY'
  | 'UNDER_REVIEW'
  | 'AMBIGUOUS'
  | 'NO_MATCH'
  | 'EMPTY';

export interface ResolvedLocation {
  status: LocationStatus;
  /** Set for MATCHED, MATCHED_FORMER_WILAYA (the NEW wilaya) and WILAYA_ONLY only. */
  wilayaCode: number | null;
  /** Set for MATCHED and MATCHED_FORMER_WILAYA only. */
  communeCode: number | null;
  /** What the commune text could mean, for a person to look at. */
  candidates: CommuneCandidate[];
}

export interface LocationText {
  wilayaText?: string | null;
  communeText?: string | null;
}

function unresolved(status: LocationStatus, candidates: CommuneCandidate[] = []): ResolvedLocation {
  return { status, wilayaCode: null, communeCode: null, candidates };
}

/** Null when no candidate is exact, so that the caller can look somewhere else. */
function decide(
  candidates: CommuneCandidate[],
  status: 'MATCHED' | 'MATCHED_FORMER_WILAYA',
  reviewed: boolean | undefined,
): ResolvedLocation | null {
  const [first, ...others] = candidates.filter((c) => c.match === 'exact');
  if (!first) return null;
  if (others.length > 0) return unresolved('AMBIGUOUS', candidates);
  const { code, wilayaCode } = first.commune;
  if (isCommuneUnderReview(code, reviewed)) return unresolved('UNDER_REVIEW', candidates);
  return { status, wilayaCode, communeCode: code, candidates };
}

/**
 * The one rule that turns the old wilaya and commune text into codes (backfill, old app
 * updates, Excel import). Only one exact candidate sets a commune.
 *
 * With a wilaya text, the commune is looked for in that wilaya, then among the communes that
 * left it. `reviewed` exists for tests; callers leave it out.
 */
export function resolveLocation(
  { wilayaText, communeText }: LocationText,
  { reviewed }: { reviewed?: boolean } = {},
): ResolvedLocation {
  const wilaya = wilayaText?.trim() ?? '';
  const commune = communeText?.trim() ?? '';

  if (!wilaya) {
    if (!commune) return unresolved('EMPTY');
    const candidates = findCommune(commune);
    return decide(candidates, 'MATCHED', reviewed) ?? unresolved('NO_MATCH', candidates);
  }

  const wilayaCode = findWilaya(wilaya);
  if (wilayaCode === null) {
    return unresolved('NO_MATCH', commune ? findCommune(commune) : []);
  }
  if (!commune) {
    return { status: 'WILAYA_ONLY', wilayaCode, communeCode: null, candidates: [] };
  }

  const current = findCommune(commune, wilayaCode);
  const inCurrent = decide(current, 'MATCHED', reviewed);
  if (inCurrent) return inCurrent;
  const former = matchAmong(
    commune,
    COMMUNES.filter((c) => c.formerWilayaCodes.includes(wilayaCode)),
  );
  return (
    decide(former, 'MATCHED_FORMER_WILAYA', reviewed) ??
    unresolved('NO_MATCH', [...current, ...former])
  );
}
